use std::{fs::File, io::Read};

use unicodex_core::{cid_for_bytes, decode_node, Node, ObjectStore};

use crate::program_module::runtime::protocol_descriptor::model::{
    ExpectedComponent, MAX_PEER_PROTOCOL_BYTES,
};

pub(super) struct Verification {
    pub(super) actual_cid: Option<String>,
    pub(super) canonical_bytes: Option<usize>,
    pub(super) verified: bool,
}

pub(super) fn verify(store: &ObjectStore, expected: &ExpectedComponent) -> Verification {
    let Some(path) = store.path_for(&expected.cid).ok() else {
        return missing();
    };
    let Ok(file) = File::open(path) else {
        return missing();
    };
    let mut bytes = Vec::with_capacity(MAX_PEER_PROTOCOL_BYTES + 1);
    if file
        .take((MAX_PEER_PROTOCOL_BYTES + 1) as u64)
        .read_to_end(&mut bytes)
        .is_err()
        || bytes.len() > MAX_PEER_PROTOCOL_BYTES
    {
        return Verification {
            actual_cid: None,
            canonical_bytes: Some(bytes.len()),
            verified: false,
        };
    }
    let actual_cid = cid_for_bytes(&bytes);
    let decoded = matches!(decode_node(&bytes), Ok(Node::Value(_)));
    Verification {
        verified: actual_cid == expected.cid && bytes == expected.canonical && decoded,
        actual_cid: Some(actual_cid),
        canonical_bytes: Some(bytes.len()),
    }
}

fn missing() -> Verification {
    Verification {
        actual_cid: None,
        canonical_bytes: None,
        verified: false,
    }
}

